package com.asmj.marketplace.engagement;
import java.math.BigDecimal; import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document;
@Document("discount_coupons") public class DiscountCoupon { public enum DiscountType{PERCENT,FIXED} @Id private String id; @Indexed(unique=true) private String code; private String description; private DiscountType discountType=DiscountType.PERCENT; private BigDecimal value=BigDecimal.ZERO; private BigDecimal minimumOrder=BigDecimal.ZERO; private BigDecimal maximumDiscount; private boolean active=true; private Instant startsAt; private Instant endsAt; private Integer usageLimit; private int usageCount; private Instant createdAt=Instant.now(); public String getId(){return id;} public void setId(String v){id=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public DiscountType getDiscountType(){return discountType;} public void setDiscountType(DiscountType v){discountType=v;} public BigDecimal getValue(){return value;} public void setValue(BigDecimal v){value=v;} public BigDecimal getMinimumOrder(){return minimumOrder;} public void setMinimumOrder(BigDecimal v){minimumOrder=v;} public BigDecimal getMaximumDiscount(){return maximumDiscount;} public void setMaximumDiscount(BigDecimal v){maximumDiscount=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public Instant getStartsAt(){return startsAt;} public void setStartsAt(Instant v){startsAt=v;} public Instant getEndsAt(){return endsAt;} public void setEndsAt(Instant v){endsAt=v;} public Integer getUsageLimit(){return usageLimit;} public void setUsageLimit(Integer v){usageLimit=v;} public int getUsageCount(){return usageCount;} public void setUsageCount(int v){usageCount=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} }
